import{FakeObservables}from"chrome://resources/ash/common/fake_observables.js";import{assert}from"chrome://resources/js/assert.js";export const ON_NETWORK_LIST_CHANGED_METHOD_NAME="NetworkListObserver_onNetworkListChanged";const ON_NETWORK_STATE_CHANGED_METHOD_NAME="NetworkStateObserver_onNetworkStateChanged";export class FakeNetworkHealthProvider{constructor(){this.observables=new FakeObservables;this.observeNetworkListPromise=null;this.observeNetworkStatePromise=null;this.registerObservables()}observeNetworkList(remote){this.observeNetworkListPromise=this.observe(ON_NETWORK_LIST_CHANGED_METHOD_NAME,(networkGuidInfo=>{remote.onNetworkListChanged(networkGuidInfo.networkGuids,networkGuidInfo.activeGuid)}))}observeNetwork(remote,guid){this.observeNetworkStatePromise=this.observeWithArg(ON_NETWORK_STATE_CHANGED_METHOD_NAME,guid,(network=>{remote.onNetworkStateChanged(network)}))}setFakeNetworkGuidInfo(networkGuidInfoList){this.observables.setObservableData(ON_NETWORK_LIST_CHANGED_METHOD_NAME,networkGuidInfoList)}setFakeNetworkState(guid,networkStateList){this.observables.setObservableDataForArg(ON_NETWORK_STATE_CHANGED_METHOD_NAME,guid,networkStateList)}getObserveNetworkListPromiseForTesting(){assert(this.observeNetworkListPromise);return this.observeNetworkListPromise}getObserveNetworkStatePromiseForTesting(){assert(this.observeNetworkStatePromise);return this.observeNetworkStatePromise}triggerNetworkListObserver(){this.observables.trigger(ON_NETWORK_LIST_CHANGED_METHOD_NAME)}startTriggerInterval(methodName,intervalMs){this.observables.startTriggerOnInterval(methodName,intervalMs)}stopTriggerIntervals(){this.observables.stopAllTriggerIntervals()}registerObservables(){this.observables.register(ON_NETWORK_LIST_CHANGED_METHOD_NAME);this.observables.registerObservableWithArg(ON_NETWORK_STATE_CHANGED_METHOD_NAME)}reset(){this.observables.stopAllTriggerIntervals();this.observables=new FakeObservables;this.registerObservables()}observe(methodName,callback){return new Promise((resolve=>{this.observables.observe(methodName,callback);this.observables.trigger(methodName);resolve()}))}observeWithArg(methodName,arg,callback){return new Promise((resolve=>{this.observables.observeWithArg(methodName,arg,callback);this.observables.triggerWithArg(methodName,arg);resolve()}))}}